### Basic CRUD Operations

```cypher
// ══════════════════════════════════════════
// CREATE Nodes
// ══════════════════════════════════════════

// Create a person node
CREATE (p:Person {name: "Elon Musk", age: 52, nationality: "American"})

// Create an organization
CREATE (o:Organization {name: "Tesla", founded: 2003, industry: "Automotive"})

// Create multiple nodes at once
CREATE 
  (a:Person {name: "Jeff Bezos"}),
  (b:Organization {name: "Amazon", founded: 1994}),
  (c:Organization {name: "Blue Origin", founded: 2000})

// ══════════════════════════════════════════
// CREATE Relationships
// ══════════════════════════════════════════

// Match existing nodes then create relationship
MATCH (p:Person {name: "Elon Musk"})
MATCH (o:Organization {name: "Tesla"})
CREATE (p)-[:FOUNDED {year: 2003}]->(o)
CREATE (p)-[:CEO_OF {since: 2008}]->(o)

// Create nodes AND relationships in one query
MERGE (p:Person {name: "Elon Musk"})
MERGE (o:Organization {name: "SpaceX"})
MERGE (p)-[:FOUNDED {year: 2002}]->(o)

// ══════════════════════════════════════════
// READ / MATCH Queries
// ══════════════════════════════════════════

// Find all persons
MATCH (p:Person) RETURN p

// Find specific person
MATCH (p:Person {name: "Elon Musk"}) RETURN p

// Find all organizations Elon Musk founded
MATCH (p:Person {name: "Elon Musk"})-[:FOUNDED]->(o:Organization)
RETURN o.name, o.founded

// Find 2-hop connections (what did founders of Tesla also found?)
MATCH (p:Person)-[:FOUNDED]->(o1:Organization {name: "Tesla"})
MATCH (p)-[:FOUNDED]->(o2:Organization)
WHERE o2.name <> "Tesla"
RETURN p.name AS Person, o2.name AS Other_Company

// Find shortest path between two entities
MATCH path = shortestPath(
  (a:Person {name: "Elon Musk"})-[*]-(b:Organization {name: "GitHub"})
)
RETURN path

// Variable-length path (1 to 3 hops)
MATCH (p:Person {name: "Elon Musk"})-[*1..3]->(x)
RETURN x.name, labels(x)

// ══════════════════════════════════════════
// GRAPH ANALYTICS QUERIES
// ══════════════════════════════════════════

// PageRank-style: Find most connected entities
MATCH (n)-[r]-()
RETURN n.name, count(r) AS degree
ORDER BY degree DESC
LIMIT 10

// Find all communities (connected components)
CALL gds.wcc.stream('myGraph')
YIELD nodeId, componentId
RETURN gds.util.asNode(nodeId).name AS name, componentId
ORDER BY componentId

// Betweenness centrality (key bridge nodes)
CALL gds.betweenness.stream('myGraph')
YIELD nodeId, score
RETURN gds.util.asNode(nodeId).name AS name, score
ORDER BY score DESC
LIMIT 5
```
